cat > rawsql.js << 'EOF'
const { PrismaClient } = require('@prisma/client');
const prisma = new PrismaClient();

async function main() {
  const count = await prisma.$queryRaw`SELECT COUNT(*) as cnt FROM User`;
  await prisma.$executeRaw`UPDATE User SET name = UPPER(name)`;
  const users = await prisma.user.findMany();
  const fs = require('fs');
  fs.writeFileSync(
    '/home/user/myproject/rawsql_result.json',
    JSON.stringify({ countResult: count, users }, null, 2)
  );
  console.log('Done');
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });
EOF

